import { ConnectionConfig, ScriptFile } from '../types';

export const generateConfigIni = (cfg: ConnectionConfig): string => {
  return `; ====================================================================
; Remote scrcpy v3.3.4 + Tailscale Encrypted Remote Access Configuration
; Generated by Remote scrcpy Control Suite
; ====================================================================

[Device]
PHONE_NAME=${cfg.phoneName || 'My-Android-Phone'}
PHONE_TAILSCALE_IP=${cfg.tailscaleIp || '100.x.y.z'}
ADB_PORT=${cfg.port || 5555}

[ScrcpyStream]
VIDEO_BITRATE=${cfg.videoBitrate}
MAX_FPS=${cfg.maxFps}
MAX_SIZE=${cfg.maxSize}
VIDEO_CODEC=${cfg.videoCodec}
FORWARD_AUDIO=${cfg.forwardAudio ? 'true' : 'false'}
TURN_SCREEN_OFF=${cfg.turnScreenOff ? 'true' : 'false'}
STAY_AWAKE=${cfg.stayAwake ? 'true' : 'false'}
CUSTOM_FLAGS=${cfg.customFlags}
`;
};

export const generateSetupPs1 = (cfg: ConnectionConfig): string => {
  return `# ==============================================================================
# Persistent Remote Android Access Setup Wizard (PowerShell)
# Configured for: scrcpy-win64-v3.3.4 & Tailscale Encrypted WireGuard Tunnel
# ==============================================================================

Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "  Remote scrcpy v3.3.4 - Automated Windows Setup Wizard    " -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host ""

$ScriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$ScrcpyFolder = Join-Path $ScriptDir "scrcpy-win64-v3.3.4"
$AdbExe = Join-Path $ScrcpyFolder "adb.exe"
$ScrcpyExe = Join-Path $ScrcpyFolder "scrcpy.exe"

# 1. Verify scrcpy v3.3.4 binaries
if (-not (Test-Path $AdbExe) -or -not (Test-Path $ScrcpyExe)) {
    Write-Host "[ERROR] Could not locate scrcpy-win64-v3.3.4 binaries!" -ForegroundColor Red
    Write-Host "Please ensure 'scrcpy-win64-v3.3.4' is extracted in: $ScriptDir" -ForegroundColor Yellow
    Pause
    exit 1
}

Write-Host "[OK] Detected scrcpy v3.3.4 at: $ScrcpyFolder" -ForegroundColor Green
Write-Host ""

# 2. Check Tailscale status on Windows
Write-Host "[1/4] Checking Windows Tailscale installation..." -ForegroundColor Yellow
$tailscaleCmd = Get-Command "tailscale" -ErrorAction SilentlyContinue
if ($tailscaleCmd) {
    Write-Host "[OK] Tailscale CLI detected." -ForegroundColor Green
    $tailscaleStatus = & tailscale status 2>&1
    Write-Host "Tailscale state summary:" -ForegroundColor Gray
    $tailscaleStatus | Select-Object -First 4 | ForEach-Object { Write-Host "   $_" -ForegroundColor DarkGray }
} else {
    Write-Host "[INFO] Tailscale CLI not in global PATH (standard GUI installation)." -ForegroundColor DarkYellow
    Write-Host "Make sure the Tailscale desktop client is running and signed in." -ForegroundColor DarkYellow
}
Write-Host ""

# 3. Detect USB-connected Android phone
Write-Host "[2/4] Detecting Android Phone connected via USB..." -ForegroundColor Yellow
Write-Host "Ensure USB Debugging is ON and tap 'Always allow from this computer'." -ForegroundColor Cyan
Write-Host "Scanning devices via ADB..." -ForegroundColor Gray

& $AdbExe kill-server | Out-Null
Start-Sleep -Seconds 1
$devices = & $AdbExe devices

Write-Host "$devices" -ForegroundColor Gray

$attachedDevices = $devices | Where-Object { $_ -match "\tdevice$" }
if ($attachedDevices.Count -eq 0) {
    Write-Host ""
    Write-Host "[WARNING] No authorized USB Android device found!" -ForegroundColor Red
    Write-Host "Steps to fix:" -ForegroundColor Yellow
    Write-Host "  1. Connect your phone via USB cable." -ForegroundColor White
    Write-Host "  2. Go to Settings > Developer Options > Enable 'USB debugging'." -ForegroundColor White
    Write-Host "  3. Unlock phone screen and accept RSA Authorization prompt ('Always allow')." -ForegroundColor White
    Write-Host "Press any key once phone is plugged in and authorized to retry..." -ForegroundColor Cyan
    $null = $Host.UI.RawUI.ReadKey("NoEcho,IncludeKeyDown")
    $devices = & $AdbExe devices
    $attachedDevices = $devices | Where-Object { $_ -match "\tdevice$" }
}

if ($attachedDevices.Count -gt 0) {
    Write-Host "[OK] Android device authorized via USB!" -ForegroundColor Green
    
    # 4. Enable TCP/IP mode on port 5555
    Write-Host ""
    Write-Host "[3/4] Enabling ADB TCP/IP mode on port 5555..." -ForegroundColor Yellow
    $tcpipResult = & $AdbExe tcpip ${cfg.port}
    Write-Host "ADB Response: $tcpipResult" -ForegroundColor Cyan
    Write-Host "[OK] adbd is now listening on TCP port ${cfg.port} on all phone interfaces (including Tailscale)." -ForegroundColor Green
} else {
    Write-Host "[NOTICE] Proceeding without active USB pairing (manual configuration mode)." -ForegroundColor Yellow
}

Write-Host ""
Write-Host "[4/4] Writing configuration file..." -ForegroundColor Yellow
$ConfigContent = @"
[Device]
PHONE_NAME=${cfg.phoneName}
PHONE_TAILSCALE_IP=${cfg.tailscaleIp}
ADB_PORT=${cfg.port}

[ScrcpyStream]
VIDEO_BITRATE=${cfg.videoBitrate}
MAX_FPS=${cfg.maxFps}
MAX_SIZE=${cfg.maxSize}
VIDEO_CODEC=${cfg.videoCodec}
FORWARD_AUDIO=${cfg.forwardAudio.toString()}
TURN_SCREEN_OFF=${cfg.turnScreenOff.toString()}
STAY_AWAKE=${cfg.stayAwake.toString()}
CUSTOM_FLAGS=${cfg.customFlags}
"@

$ConfigDir = Join-Path $ScriptDir "config"
if (-not (Test-Path $ConfigDir)) { New-Item -ItemType Directory -Path $ConfigDir | Out-Null }
$ConfigFile = Join-Path $ConfigDir "connection.ini"
Set-Content -Path $ConfigFile -Value $ConfigContent -Encoding UTF8

Write-Host "[OK] Saved configuration to $ConfigFile" -ForegroundColor Green
Write-Host ""
Write-Host "==========================================================" -ForegroundColor Green
Write-Host "  SETUP COMPLETE! You can now disconnect the USB cable.   " -ForegroundColor Green
Write-Host "  To launch remote screen mirroring anytime, run:        " -ForegroundColor White
Write-Host "  --> start-remote.bat                                    " -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Green
Write-Host ""
Pause
`;
};

export const generateStartRemoteBat = (cfg: ConnectionConfig): string => {
  const audioFlag = cfg.forwardAudio ? '' : '--no-audio';
  const screenOffFlag = cfg.turnScreenOff ? '--turn-screen-off' : '';
  const stayAwakeFlag = cfg.stayAwake ? '--stay-awake' : '';
  const sizeFlag = cfg.maxSize > 0 ? `-m ${cfg.maxSize}` : '';

  return `@echo off
setlocal enabledelayedexpansion
title Remote scrcpy v3.3.4 Launcher - Tailscale VPN

:: ==============================================================================
:: Remote scrcpy Session Launcher (Tailscale WireGuard Protected)
:: ==============================================================================

:: Navigate to script directory
cd /d "%~dp0"

set "SCRCPY_DIR=%~dp0scrcpy-win64-v3.3.4"
set "CONFIG_FILE=%~dp0config\\connection.ini"

:: Verify scrcpy directory exists
if not exist "%SCRCPY_DIR%\\scrcpy.exe" (
    echo [ERROR] scrcpy.exe not found in: %SCRCPY_DIR%
    echo Please make sure the 'scrcpy-win64-v3.3.4' directory is in the same folder.
    echo.
    pause
    exit /b 1
)

:: Default Parameters (Overridden if config\\connection.ini exists)
set "PHONE_IP=${cfg.tailscaleIp || '100.x.y.z'}"
set "ADB_PORT=${cfg.port || 5555}"
set "BITRATE=${cfg.videoBitrate}"
set "MAX_FPS=${cfg.maxFps}"
set "MAX_SIZE=${cfg.maxSize}"
set "AUDIO_FLAG=${audioFlag}"
set "SCREEN_OFF=${screenOffFlag}"
set "STAY_AWAKE=${stayAwakeFlag}"
set "CODEC=${cfg.videoCodec}"
set "EXTRA_FLAGS=${cfg.customFlags}"

:: Load INI if present
if exist "%CONFIG_FILE%" (
    for /f "tokens=1,2 delims==" %%A in ('type "%CONFIG_FILE%" ^| findstr /r "^[A-Za-z]"') do (
        if "%%A"=="PHONE_TAILSCALE_IP" set "PHONE_IP=%%B"
        if "%%A"=="ADB_PORT" set "ADB_PORT=%%B"
        if "%%A"=="VIDEO_BITRATE" set "BITRATE=%%B"
        if "%%A"=="MAX_FPS" set "MAX_FPS=%%B"
        if "%%A"=="MAX_SIZE" set "MAX_SIZE=%%B"
    )
)

cls
echo ====================================================================
echo   REMOTE SCRCPY SESSION LAUNCHER (v3.3.4)
echo ====================================================================
echo Target Device IP : !PHONE_IP! (Tailscale VPN)
echo Target ADB Port  : !ADB_PORT!
echo Video Bitrate    : !BITRATE!
echo Max Frame Rate   : !MAX_FPS! fps
echo Resolution Limit : !MAX_SIZE! px
echo Security Layer   : Tailscale Encrypted WireGuard Mesh (No Public Ports)
echo ====================================================================
echo.

if "!PHONE_IP!"=="100.x.y.z" (
    echo [!] Warning: You have not configured your phone's Tailscale IP yet!
    set /p "PHONE_IP=Enter your phone's 100.x.y.z Tailscale IP: "
)

echo [*] Step 1: Checking Tailscale connectivity to !PHONE_IP!...
ping -n 1 -w 1500 !PHONE_IP! >nul 2>&1
if errorlevel 1 (
    echo [!] WARNING: Cannot ping !PHONE_IP! via Tailscale.
    echo     Please verify:
    echo     1. Tailscale is connected on this PC.
    echo     2. Tailscale is connected on your Android phone.
    echo     3. Tailscale Battery Optimization is disabled on Android.
    echo.
    echo Attempting ADB connection regardless...
) else (
    echo [OK] Phone reached through encrypted Tailscale tunnel.
)

echo.
echo [*] Step 2: Connecting ADB to !PHONE_IP!:!ADB_PORT!...
"%SCRCPY_DIR%\\adb.exe" connect !PHONE_IP!:!ADB_PORT!

echo.
echo [*] Step 3: Checking ADB device authorization...
"%SCRCPY_DIR%\\adb.exe" devices | findstr /c:"!PHONE_IP!:!ADB_PORT!" | findstr /i "device" >nul 2>&1
if errorlevel 1 (
    echo.
    echo [!] Connection check failed or device unauthorized.
    echo If it says 'unauthorized', unlock phone and accept the prompt.
    echo If it says 'offline' or 'connection refused', the phone may have rebooted
    echo and adb tcpip needs to be re-enabled once via USB.
    echo.
    echo Reviewing full ADB device list:
    "%SCRCPY_DIR%\\adb.exe" devices
    echo.
    pause
)

echo.
echo [*] Step 4: Launching scrcpy v3.3.4 remote mirroring...
echo [TIP] Press Alt+O to turn phone screen on/off.
echo [TIP] Press Alt+H for Home, Alt+B for Back, Alt+S for App Switcher.
echo.

set "CMD_ARGS=-s !PHONE_IP!:!ADB_PORT! --video-bit-rate=!BITRATE! --max-fps=!MAX_FPS!"
if not "!MAX_SIZE!"=="0" set "CMD_ARGS=!CMD_ARGS! -m !MAX_SIZE!"
if not "!CODEC!"=="" set "CMD_ARGS=!CMD_ARGS! --video-codec=!CODEC!"
if not "!AUDIO_FLAG!"=="" set "CMD_ARGS=!CMD_ARGS! !AUDIO_FLAG!"
if not "!SCREEN_OFF!"=="" set "CMD_ARGS=!CMD_ARGS! !SCREEN_OFF!"
if not "!STAY_AWAKE!"=="" set "CMD_ARGS=!CMD_ARGS! !STAY_AWAKE!"
if not "!EXTRA_FLAGS!"=="" set "CMD_ARGS=!CMD_ARGS! !EXTRA_FLAGS!"

echo Executing: scrcpy.exe !CMD_ARGS!
"%SCRCPY_DIR%\\scrcpy.exe" !CMD_ARGS! --pause-on-exit=if-error

echo.
echo Session ended. Disconnecting ADB TCP/IP session...
"%SCRCPY_DIR%\\adb.exe" disconnect !PHONE_IP!:!ADB_PORT! >nul 2>&1
echo Done.
`;
};

export const generateReconnectBat = (cfg: ConnectionConfig): string => {
  return `@echo off
setlocal enabledelayedexpansion
title Quick Reconnect - Remote scrcpy v3.3.4
cd /d "%~dp0"

set "SCRCPY_DIR=%~dp0scrcpy-win64-v3.3.4"
set "PHONE_IP=${cfg.tailscaleIp || '100.x.y.z'}"
set "ADB_PORT=${cfg.port || 5555}"

:: Load from config if available
if exist "%~dp0config\\connection.ini" (
    for /f "tokens=1,2 delims==" %%A in ('type "%~dp0config\\connection.ini" ^| findstr /r "^[A-Za-z]"') do (
        if "%%A"=="PHONE_TAILSCALE_IP" set "PHONE_IP=%%B"
        if "%%A"=="ADB_PORT" set "ADB_PORT=%%B"
    )
)

echo [*] Resetting local ADB server...
"%SCRCPY_DIR%\\adb.exe" disconnect >nul 2>&1
"%SCRCPY_DIR%\\adb.exe" kill-server >nul 2>&1
timeout /t 1 >nul
"%SCRCPY_DIR%\\adb.exe" start-server >nul 2>&1

echo [*] Reconnecting to !PHONE_IP!:!ADB_PORT!...
"%SCRCPY_DIR%\\adb.exe" connect !PHONE_IP!:!ADB_PORT!

echo [*] Testing connection...
"%SCRCPY_DIR%\\adb.exe" devices
echo.
echo You can now run start-remote.bat to launch screen mirroring.
timeout /t 3
`;
};

export const generateDisconnectBat = (cfg: ConnectionConfig): string => {
  return `@echo off
title Disconnect Remote Android Session
cd /d "%~dp0"
set "SCRCPY_DIR=%~dp0scrcpy-win64-v3.3.4"
set "PHONE_IP=${cfg.tailscaleIp || '100.x.y.z'}"
set "ADB_PORT=${cfg.port || 5555}"

if exist "%~dp0config\\connection.ini" (
    for /f "tokens=1,2 delims==" %%A in ('type "%~dp0config\\connection.ini" ^| findstr /r "^[A-Za-z]"') do (
        if "%%A"=="PHONE_TAILSCALE_IP" set "PHONE_IP=%%B"
        if "%%A"=="ADB_PORT" set "ADB_PORT=%%B"
    )
)

echo ====================================================================
echo   Disconnecting Remote Android Session
echo ====================================================================
echo.

echo [*] Stopping active scrcpy processes...
taskkill /f /im scrcpy.exe >nul 2>&1

echo [*] Disconnecting ADB from !PHONE_IP!:!ADB_PORT!...
"%SCRCPY_DIR%\\adb.exe" disconnect !PHONE_IP!:!ADB_PORT!

echo [*] Killing local ADB daemon...
"%SCRCPY_DIR%\\adb.exe" kill-server

echo.
echo [OK] Remote screen session and ADB tunnel disconnected.
echo Phone remains secure. Screen mirroring has stopped.
echo.
pause
`;
};

export const generateInitialUsbSetupBat = (cfg: ConnectionConfig): string => {
  return `@echo off
title 01 - Initial USB Authorization and TCP/IP Binding
cd /d "%~dp0\\.."
set "SCRCPY_DIR=%~dp0\\..\\scrcpy-win64-v3.3.4"

cls
echo ====================================================================
echo   STEP 1: INITIAL USB SETUP AND WIRELESS TCP/IP ENABLER
echo ====================================================================
echo   This one-time step authorizes your PC and binds adbd to port ${cfg.port}.
echo.
echo Requirements:
echo   1. Android Settings > About Phone > Tap 'Build Number' 7 times.
echo   2. Android Settings > Developer Options > Enable 'USB Debugging'.
echo   3. Plug phone into this Windows PC with a USB cable.
echo   4. On phone screen: CHECK 'Always allow from this computer' and tap 'Allow'.
echo ====================================================================
echo.

pause

echo [*] Restarting ADB server...
"%SCRCPY_DIR%\\adb.exe" kill-server
"%SCRCPY_DIR%\\adb.exe" start-server

echo [*] Checking for attached USB device...
"%SCRCPY_DIR%\\adb.exe" devices

echo.
echo [*] Enabling TCP/IP mode on port ${cfg.port}...
"%SCRCPY_DIR%\\adb.exe" tcpip ${cfg.port}
if errorlevel 1 (
    echo.
    echo [ERROR] Failed to enable TCP/IP mode.
    echo Please ensure phone is connected via USB and screen unlocked.
    echo.
    pause
    exit /b 1
)

echo.
echo ====================================================================
echo [SUCCESS] adbd is now listening on port ${cfg.port} on your Android device!
echo.
echo You may now:
echo   1. Unplug the USB cable.
echo   2. Ensure Tailscale is active on both devices.
echo   3. Run 'start-remote.bat' to mirror over Wi-Fi, 4G, or external networks.
echo ====================================================================
echo.
pause
`;
};

export const generateRevokeAndUninstallBat = (): string => {
  return `@echo off
title 99 - Revoke Access and Secure Removal
cd /d "%~dp0\\.."
set "SCRCPY_DIR=%~dp0\\..\\scrcpy-win64-v3.3.4"

cls
echo ====================================================================
echo   SECURE REMOVAL & ACCESS REVOCATION PROCEDURE
echo ====================================================================
echo This script removes all PC-side connections and guides you to revoke
echo authorizations on your Android phone.
echo ====================================================================
echo.

echo [*] Step 1: Stopping all scrcpy instances...
taskkill /f /im scrcpy.exe >nul 2>&1

echo [*] Step 2: Disconnecting all active ADB connections...
"%SCRCPY_DIR%\\adb.exe" disconnect >nul 2>&1
"%SCRCPY_DIR%\\adb.exe" kill-server >nul 2>&1

echo [*] Step 3: Deleting PC-side ADB authorization keys if desired...
set "ADB_KEY_DIR=%USERPROFILE%\\.android"
if exist "%ADB_KEY_DIR%\\adbkey" (
    echo Found Windows ADB keys in: %ADB_KEY_DIR%
    choice /M "Do you want to delete PC authorization keys (adbkey, adbkey.pub)?"
    if errorlevel 2 goto skip_keys
    del /f /q "%ADB_KEY_DIR%\\adbkey" "%ADB_KEY_DIR%\\adbkey.pub" >nul 2>&1
    echo [OK] Removed PC ADB keys.
)
:skip_keys

echo.
echo ====================================================================
echo   MANUAL ACTIONS REQUIRED ON YOUR ANDROID PHONE:
echo ====================================================================
echo 1. Open Phone Settings > Developer Options.
echo 2. Tap 'Revoke USB debugging authorizations'.
echo    (This invalidates all previously approved PC keys immediately).
echo 3. Toggle OFF 'USB Debugging' and 'Wireless Debugging'.
echo 4. In Tailscale app: Disconnect and/or sign out.
echo 5. Reboot phone to completely close TCP port 5555.
echo ====================================================================
echo.
pause
`;
};

export const generateReadmeMd = (cfg: ConnectionConfig): string => {
  return `# Remote scrcpy v3.3.4 Remote Android Control System

A beginner-friendly, secure, zero-public-port solution for persistent remote Android screen mirroring and keyboard/mouse control across different internet networks.

## Core Security Guarantee
- **Zero Port Forwarding**: Port 5555 is never exposed to the public internet.
- **Tailscale WireGuard Mesh**: End-to-end encrypted peer-to-peer virtual network. Only authenticated devices in your private Tailnet can access the phone.
- **Strict Informed Consent**: No hidden background recording, no stealth payloads, fully revocable.

---

## Folder Structure

\`\`\`
Remote-scrcpy-Suite/
├── scrcpy-win64-v3.3.4/           # Official scrcpy v3.3.4 release (adb, scrcpy.exe, DLLs)
│   ├── adb.exe
│   ├── scrcpy.exe
│   ├── scrcpy-server
│   └── ...
├── config/
│   └── connection.ini             # Device IP, port, and stream parameters
├── scripts/
│   ├── 01_initial_usb_setup.bat   # One-time USB authorization & tcpip binding
│   ├── 02_reconnect.bat           # Quick ADB daemon reset & reconnect
│   ├── 03_disconnect.bat          # Clean termination of remote sessions
│   └── 99_revoke_and_uninstall.bat# Key wiping & revocation instructions
├── setup.ps1                      # Windows PowerShell Setup Wizard
├── start-remote.bat               # Daily 1-click double-click launcher
└── README.md                      # This documentation
\`\`\`

---

## Step-by-Step Setup Guide

### Phase 1: Android Phone Preparation (One-Time)
1. Open **Settings > About Phone**.
2. Scroll to **Build Number** and tap it **7 times** until "You are now a developer!" appears.
3. Go back to **Settings > System > Developer Options**.
4. Enable **USB Debugging**.
5. Enable **Stay awake while charging** (optional, recommended for remote use).
6. (Xiaomi/MIUI only): Enable "USB debugging (Security settings)" to allow remote clicks/keyboard input.

### Phase 2: Tailscale Private Mesh VPN (Enables Remote Across Networks)
1. Install **Tailscale** on your Windows laptop from [tailscale.com](https://tailscale.com) and log in.
2. Install **Tailscale** on your Android phone from Google Play Store or F-Droid and log in with the **same account**.
3. In Android Tailscale app:
   - Toggle **Connect** ON.
   - Note the assigned **100.x.y.z IP address** (e.g., \`${cfg.tailscaleIp || '100.85.12.34'}\`).
   - Go to phone **Settings > Battery > Battery Optimization / Background usage** and set Tailscale to **Unrestricted** so Android does not kill the VPN when the screen is locked.

### Phase 3: Initial USB Authorization & TCP/IP Mode Binding
1. Connect your Android phone to your Windows laptop with a USB cable.
2. An Android pop-up will appear: **"Allow USB debugging?"**.
3. **CHECK the box: "Always allow from this computer"** and tap **Allow**.
4. Run \`scripts\\01_initial_usb_setup.bat\` (or \`setup.ps1\`).
   - This executes: \`adb tcpip ${cfg.port}\`.
   - The phone's internal adb daemon now listens on port ${cfg.port} across all interfaces (including Tailscale).
5. **Unplug the USB cable.**

### Phase 4: Remote Screen Mirroring Anywhere
1. Ensure Tailscale is connected on both your PC and phone.
2. Double-click \`start-remote.bat\` on your Windows laptop.
3. Your Android screen will appear instantly in a responsive, low-latency window!

---

## What Genuinely Persists vs What Android Resets

| Event | Persistence Reality | Action Required |
|---|---|---|
| **RSA Computer Authorization** | **PERMANENT** | Kept in \`/data/misc/adb/adb_keys\` until manually revoked. |
| **Tailscale VPN IP (100.x.y.z)** | **PERMANENT** | Same static mesh IP even when moving between Wi-Fi and 5G. |
| **Switching Networks (Wi-Fi <-> 5G)** | **PERSISTENT** | WireGuard seamlessly migrates active UDP sockets. |
| **Phone Reboot** | **DOES NOT PERSIST** | Android OS resets \`adbd\` TCP/IP port to disabled. |
| **Screen Lock / PIN** | **CONTROLLABLE** | scrcpy displays lockscreen; enter PIN via keyboard. |
| **Direct Boot (After Reboot)** | **ADB BLOCKED** | Android File-Based Encryption blocks ADB until initial unlock. |

---

## Scrcpy Keyboard Shortcuts
- \`Alt + h\` : Home Button
- \`Alt + b\` : Back Button
- \`Alt + s\` : App Switcher (Recent Apps)
- \`Alt + o\` : Turn physical phone screen ON
- \`Alt + p\` : Power Button (Lock/Unlock)
- \`Ctrl + v\` : Paste PC clipboard directly into Android
- \`Ctrl + c\` : Copy Android clipboard into PC
- \`Alt + Up / Down\` : Volume Up / Down

---

## Disconnect & Uninstallation
- To disconnect immediately: Run \`scripts\\03_disconnect.bat\`.
- To completely revoke PC access: Run \`scripts\\99_revoke_and_uninstall.bat\` and tap **Revoke USB debugging authorizations** in your phone's Developer Options.
`;
};

